using namespace System.Net
# $sub and $DID are injected by CloudLabs.
# The Resource Graph filter below uses the discovered $rg. It previously hardcoded
# '/resourceGroups/asclab/', which matches no resource in a CloudLabs deployment — the lab group is
# named ODL-DFC-<DeploymentID> — so the query returned zero rows and the challenge always failed.
# Verified 6 Oct 2026: 0 rows for the hardcoded form against the live subscription.
$rg=(Get-AzResource -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'asclab*' } | Select-Object -First 1).ResourceGroupName; if(-not $rg){ throw 'Could not locate the lab resource group: no resource named asclab* found in the subscription.' };$image='contoso-vulnerable/aspnet-core:2.1';$count=0;$found=$false;$detail='No attempt completed.'
do{$count++;try{Set-AzContext -Subscription $sub -ErrorAction Stop|Out-Null;$p=Get-AzSecurityPricing -Name Containers -ErrorAction Stop;if($p.PricingTier -ne 'Standard'){throw "Defender for Containers tier is '$($p.PricingTier)', expected Standard."};$q="securityresources | where type =~ 'microsoft.security/assessments/subassessments' | where id has '/resourceGroups/$rg/' | project id,name,properties";$rows=@(Search-AzGraph -Query $q -Subscription $sub -First 5000 -ErrorAction Stop);if($rows.Count -eq 0){throw "No Defender container assessment findings yet for resource group '$rg'. Registry image scanning runs after Defender for Containers is enabled and can take time to produce findings."};$hits=@($rows|% {$_|ConvertTo-Json -Depth 40 -Compress}|? {$_ -match '(?i)asclabcr[a-z0-9-]*' -and $_ -match [regex]::Escape($image) -and $_ -match '(?i)Unhealthy'});if($hits.Count -eq 0){throw "No Unhealthy finding references exact image '$image' in an asclabcr* registry."};$found=$true;$body=@{Status='Succeeded';Message="Defender for Containers is Standard and has $($hits.Count) Unhealthy finding(s) for '$image' in '$rg'."}|ConvertTo-Json -Compress;Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber}catch{$detail=$_.Exception.Message;$body=@{Status='Failed';Message="Challenge 4 attempt $count of 3 failed: $detail"}|ConvertTo-Json -Compress;Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber;Start-Sleep -Seconds 10}}while($count -lt 3 -and -not $found)
if(-not $found){$body=@{Status='Failed';Message="Challenge 4 failed after 3 attempts in '$rg'. Last reason: $detail"}|ConvertTo-Json -Compress;Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber}